import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "../ui/dialog";
import { Button } from "../ui/button";
import { Input } from "../ui/input";
import { Label } from "../ui/label";
import { Textarea } from "../ui/textarea";
import { Badge } from "../ui/badge";
import { Avatar, AvatarFallback } from "../ui/avatar";
import { Checkbox } from "../ui/checkbox";
import { VisuallyHidden } from "@radix-ui/react-visually-hidden";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "../ui/tabs";
import {
  Clock,
  User,
  Calendar,
  Tag,
  MessageSquare,
  CheckSquare,
  Plus,
  X,
  Trash2,
  Send,
  Save,
} from "lucide-react";
import { formatDate } from "../../utils/formatters";
import Swal from "sweetalert2";

const PRIORITY_OPTIONS = [
  { value: "low", label: "Baja", color: "bg-gray-100 text-gray-700" },
  { value: "medium", label: "Media", color: "bg-blue-100 text-blue-700" },
  { value: "high", label: "Alta", color: "bg-orange-100 text-orange-700" },
  { value: "urgent", label: "Urgente", color: "bg-red-100 text-red-700" },
];

const STATUS_OPTIONS = [
  { value: "todo", label: "Por Hacer" },
  { value: "in_progress", label: "En Progreso" },
  { value: "review", label: "En Revisión" },
  { value: "completed", label: "Completado" },
];

const UNASSIGNED_VALUE = "__unassigned__";

export const TaskDetailModal = ({
  isOpen,
  onClose,
  task,
  onUpdate,
  onDelete,
  teamMembers = [],
  readOnly = false,
}) => {
  const [editedTask, setEditedTask] = useState(null);
  const [newSubtask, setNewSubtask] = useState("");
  const [newTag, setNewTag] = useState("");
  const [newComment, setNewComment] = useState("");
  const [isEditing, setIsEditing] = useState(false);
  const [hasChanges, setHasChanges] = useState(false);

  useEffect(() => {
    if (task && isOpen) {
      console.log('📝 Task recibida:', task);
      console.log('👥 Team members:', teamMembers);
      
      setEditedTask({
        ...task,
        subtasks: task.subtasks || [],
        tags: task.tags || [],
        comments: task.comments || [],
      });
      setIsEditing(false);
      setHasChanges(false);
    }
  }, [task, isOpen]);

  if (!task || !editedTask) return null;

  const handleFieldChange = (field, value) => {
    setEditedTask(prev => ({ ...prev, [field]: value }));
    setHasChanges(true);
  };

  const handleSave = async () => {
    if (!hasChanges) {
      setIsEditing(false);
      return;
    }

    try {
      console.log('💾 Guardando tarea:', editedTask);
      await onUpdate(editedTask);
      setIsEditing(false);
      setHasChanges(false);
      
      Swal.fire({
        icon: "success",
        title: "Cambios Guardados",
        toast: true,
        position: "top-end",
        showConfirmButton: false,
        timer: 2000,
        timerProgressBar: true,
      });
    } catch (error) {
      console.error('Error saving task:', error);
      Swal.fire({
        icon: "error",
        title: "Error",
        text: "No se pudieron guardar los cambios",
        confirmButtonColor: "#dc2626",
      });
    }
  };

  const handleDelete = async () => {
    const result = await Swal.fire({
      title: "¿Eliminar Tarea?",
      text: "Esta acción no se puede deshacer",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#dc2626",
      cancelButtonColor: "#6b7280",
      confirmButtonText: "Sí, eliminar",
      cancelButtonText: "Cancelar",
    });

    if (result.isConfirmed) {
      try {
        await onDelete(task._id);
        onClose();
      } catch (error) {
        console.error('Error deleting task:', error);
      }
    }
  };

  // 🔥 ACTUALIZADO: Subtareas sin _id
  const addSubtask = () => {
    if (!newSubtask.trim()) return;

    const updatedSubtasks = [
      ...(editedTask.subtasks || []),
      {
        // ❌ NO incluir _id para subtareas
        title: newSubtask,
        completed: false,
        created_at: new Date().toISOString(),
      },
    ];
    
    handleFieldChange('subtasks', updatedSubtasks);
    setNewSubtask("");
  };

  // 🔥 ACTUALIZADO: Identificar subtareas por índice
  const toggleSubtask = (subtaskIndex) => {
    const updatedSubtasks = editedTask.subtasks.map((st, idx) =>
      idx === subtaskIndex ? { ...st, completed: !st.completed } : st
    );
    handleFieldChange('subtasks', updatedSubtasks);
  };

  // 🔥 ACTUALIZADO: Eliminar subtareas por índice
  const removeSubtask = (subtaskIndex) => {
    const updatedSubtasks = editedTask.subtasks.filter((st, idx) => idx !== subtaskIndex);
    handleFieldChange('subtasks', updatedSubtasks);
  };

  const addTag = () => {
    if (!newTag.trim() || editedTask.tags?.includes(newTag.trim())) return;

    const updatedTags = [...(editedTask.tags || []), newTag.trim()];
    handleFieldChange('tags', updatedTags);
    setNewTag("");
  };

  const removeTag = (tagToRemove) => {
    const updatedTags = editedTask.tags.filter((t) => t !== tagToRemove);
    handleFieldChange('tags', updatedTags);
  };

  const completedSubtasks = editedTask.subtasks?.filter((st) => st.completed).length || 0;
  const totalSubtasks = editedTask.subtasks?.length || 0;
  const progress = totalSubtasks > 0 ? (completedSubtasks / totalSubtasks) * 100 : 0;

  const priorityColor = PRIORITY_OPTIONS.find(p => p.value === editedTask.priority)?.color || '';
  const statusLabel = STATUS_OPTIONS.find(s => s.value === editedTask.status)?.label || '';

  const getAssignedToValue = () => {
    if (!editedTask.assigned_to) return UNASSIGNED_VALUE;
    
    if (typeof editedTask.assigned_to === 'object' && editedTask.assigned_to._id) {
      return editedTask.assigned_to._id;
    }
    
    if (typeof editedTask.assigned_to === 'string') {
      return editedTask.assigned_to;
    }
    
    return UNASSIGNED_VALUE;
  };

  const handleAssignedToChange = (value) => {
    if (value === UNASSIGNED_VALUE) {
      handleFieldChange('assigned_to', null);
    } else {
      const member = teamMembers.find(m => m._id === value);
      handleFieldChange('assigned_to', member || value);
    }
  };

  const getAssignedToName = () => {
    if (!editedTask.assigned_to) return 'Sin asignar';
    
    if (typeof editedTask.assigned_to === 'object') {
      return editedTask.assigned_to.full_name || 'Sin asignar';
    }
    
    const member = teamMembers.find(m => m._id === editedTask.assigned_to);
    return member?.full_name || 'Sin asignar';
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <div className="flex items-start justify-between">
            <div className="flex-1 pr-4">
              {isEditing ? (
                <Input
                  value={editedTask.title}
                  onChange={(e) => handleFieldChange('title', e.target.value)}
                  className="text-xl font-bold mb-2"
                  placeholder="Título de la tarea"
                />
              ) : (
                <div>
                  <VisuallyHidden>
                    <DialogTitle>{editedTask.title}</DialogTitle>
                  </VisuallyHidden>
                  <h2 className="text-2xl font-bold mb-2">{editedTask.title}</h2>
                </div>
              )}

              <div className="flex flex-wrap gap-2 mt-2">
                <Badge className={priorityColor}>
                  {PRIORITY_OPTIONS.find(p => p.value === editedTask.priority)?.label}
                </Badge>
                <Badge variant="outline">{statusLabel}</Badge>
              </div>
            </div>

            {!readOnly && (
              <div className="flex gap-2 flex-shrink-0">
                {isEditing ? (
                  <>
                    <Button
                      onClick={handleSave}
                      size="sm"
                      className="bg-green-600 hover:bg-green-700"
                      disabled={!hasChanges}
                    >
                      <Save className="w-4 h-4 mr-2" />
                      Guardar
                    </Button>
                    <Button
                      onClick={() => {
                        setEditedTask(task);
                        setIsEditing(false);
                        setHasChanges(false);
                      }}
                      variant="outline"
                      size="sm"
                    >
                      Cancelar
                    </Button>
                  </>
                ) : (
                  <>
                    <Button
                      onClick={() => setIsEditing(true)}
                      variant="outline"
                      size="sm"
                    >
                      Editar
                    </Button>
                    <Button
                      onClick={handleDelete}
                      variant="destructive"
                      size="sm"
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </>
                )}
              </div>
            )}
          </div>
        </DialogHeader>

        <Tabs defaultValue="details" className="w-full">
          <TabsList className="grid w-full grid-cols-3">
            <TabsTrigger value="details">Detalles</TabsTrigger>
            <TabsTrigger value="subtasks">
              Subtareas
              {totalSubtasks > 0 && (
                <Badge variant="outline" className="ml-2">
                  {completedSubtasks}/{totalSubtasks}
                </Badge>
              )}
            </TabsTrigger>
            <TabsTrigger value="activity">Actividad</TabsTrigger>
          </TabsList>

          {/* DETALLES TAB */}
          <TabsContent value="details" className="space-y-4 mt-4">
            <div>
              <Label>Descripción</Label>
              {isEditing ? (
                <Textarea
                  value={editedTask.description || ""}
                  onChange={(e) => handleFieldChange('description', e.target.value)}
                  rows={4}
                  placeholder="Describe la tarea..."
                  className="mt-2"
                />
              ) : (
                <p className="text-sm text-gray-600 mt-2">
                  {editedTask.description || "Sin descripción"}
                </p>
              )}
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label>Estado</Label>
                {isEditing ? (
                  <Select
                    value={editedTask.status}
                    onValueChange={(value) => handleFieldChange('status', value)}
                  >
                    <SelectTrigger className="mt-2">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {STATUS_OPTIONS.map((option) => (
                        <SelectItem key={option.value} value={option.value}>
                          {option.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                ) : (
                  <p className="text-sm text-gray-600 mt-2">{statusLabel}</p>
                )}
              </div>

              <div>
                <Label>Prioridad</Label>
                {isEditing ? (
                  <Select
                    value={editedTask.priority}
                    onValueChange={(value) => handleFieldChange('priority', value)}
                  >
                    <SelectTrigger className="mt-2">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {PRIORITY_OPTIONS.map((option) => (
                        <SelectItem key={option.value} value={option.value}>
                          {option.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                ) : (
                  <p className="text-sm text-gray-600 mt-2">
                    {PRIORITY_OPTIONS.find(p => p.value === editedTask.priority)?.label}
                  </p>
                )}
              </div>

              <div>
                <Label>Asignado a</Label>
                {isEditing ? (
                  <Select
                    value={getAssignedToValue()}
                    onValueChange={handleAssignedToChange}
                  >
                    <SelectTrigger className="mt-2">
                      <SelectValue placeholder="Seleccionar..." />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value={UNASSIGNED_VALUE}>
                        Sin asignar
                      </SelectItem>
                      
                      {teamMembers && teamMembers.length > 0 ? (
                        teamMembers.map((member) => (
                          <SelectItem key={member._id} value={member._id}>
                            {member.full_name || member.email || 'Usuario'}
                          </SelectItem>
                        ))
                      ) : (
                        <SelectItem value="no-members" disabled>
                          No hay consultores disponibles
                        </SelectItem>
                      )}
                    </SelectContent>
                  </Select>
                ) : (
                  <div className="flex items-center space-x-2 mt-2">
                    {editedTask.assigned_to ? (
                      <>
                        <Avatar className="h-6 w-6">
                          <AvatarFallback className="text-xs">
                            {getAssignedToName().split(" ").map((n) => n[0]).join("").toUpperCase()}
                          </AvatarFallback>
                        </Avatar>
                        <span className="text-sm text-gray-600">
                          {getAssignedToName()}
                        </span>
                      </>
                    ) : (
                      <span className="text-sm text-gray-400">Sin asignar</span>
                    )}
                  </div>
                )}
              </div>

              <div>
                <Label>Fecha límite</Label>
                {isEditing ? (
                  <Input
                    type="date"
                    value={editedTask.due_date ? new Date(editedTask.due_date).toISOString().split("T")[0] : ""}
                    onChange={(e) => handleFieldChange('due_date', e.target.value)}
                    className="mt-2"
                  />
                ) : (
                  <p className="text-sm text-gray-600 mt-2">
                    {editedTask.due_date ? formatDate(editedTask.due_date) : "Sin fecha"}
                  </p>
                )}
              </div>
            </div>

            <div>
              <Label>Etiquetas</Label>
              <div className="flex flex-wrap gap-2 mt-2">
                {editedTask.tags?.map((tag, idx) => (
                  <Badge
                    key={idx}
                    variant="outline"
                    className="flex items-center gap-1"
                  >
                    {tag}
                    {isEditing && (
                      <X
                        className="w-3 h-3 cursor-pointer hover:text-red-600"
                        onClick={() => removeTag(tag)}
                      />
                    )}
                  </Badge>
                ))}
                {isEditing && (
                  <div className="flex gap-2">
                    <Input
                      placeholder="Nueva etiqueta"
                      value={newTag}
                      onChange={(e) => setNewTag(e.target.value)}
                      onKeyPress={(e) => e.key === "Enter" && addTag()}
                      className="w-32"
                    />
                    <Button onClick={addTag} size="sm" type="button">
                      <Plus className="w-4 h-4" />
                    </Button>
                  </div>
                )}
              </div>
            </div>
          </TabsContent>

          {/* SUBTAREAS TAB - ACTUALIZADO */}
          <TabsContent value="subtasks" className="space-y-4 mt-4">
            {totalSubtasks > 0 && (
              <div className="mb-4">
                <div className="flex justify-between text-sm mb-2">
                  <span>Progreso</span>
                  <span>{Math.round(progress)}%</span>
                </div>
                <div className="w-full bg-gray-200 rounded-full h-2">
                  <div
                    className="bg-green-500 h-2 rounded-full transition-all"
                    style={{ width: `${progress}%` }}
                  />
                </div>
              </div>
            )}

            <div className="space-y-2">
              {editedTask.subtasks?.map((subtask, index) => (
                <div
                  key={index}
                  className="flex items-center justify-between p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors"
                >
                  <div className="flex items-center space-x-3 flex-1">
                    <Checkbox
                      checked={subtask.completed}
                      onCheckedChange={() => toggleSubtask(index)}
                      disabled={readOnly}
                    />
                    <span
                      className={`text-sm ${
                        subtask.completed ? "line-through text-gray-400" : "text-gray-700"
                      }`}
                    >
                      {subtask.title}
                    </span>
                  </div>
                  {isEditing && (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => removeSubtask(index)}
                    >
                      <X className="w-4 h-4 text-red-600" />
                    </Button>
                  )}
                </div>
              ))}
            </div>

            {!readOnly && (
              <div className="flex gap-2 mt-4">
                <Input
                  placeholder="Nueva subtarea"
                  value={newSubtask}
                  onChange={(e) => setNewSubtask(e.target.value)}
                  onKeyPress={(e) => e.key === "Enter" && addSubtask()}
                />
                <Button onClick={addSubtask} type="button">
                  <Plus className="w-4 h-4" />
                </Button>
              </div>
            )}
          </TabsContent>

          <TabsContent value="activity" className="space-y-4 mt-4">
            <div className="text-center py-8 text-gray-500">
              <MessageSquare className="w-12 h-12 mx-auto mb-3 opacity-50" />
              <p>Sistema de comentarios próximamente</p>
            </div>
          </TabsContent>
        </Tabs>
      </DialogContent>
    </Dialog>
  );
};
